// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Row-path computed BINDs whose results are not inline-packable (long strings) compile natively as runtime-interned,
 * store-canonical ids instead of turning the subtree into a generic island. These differential tests pin the four
 * consumer seams of such a computed slot: plain projection, a filter over the computed value (which must route through
 * the generic bridge — interned ids carry arbitrary type bits), a join of the computed value against stored data (which
 * requires store-first id canonicalization), and DISTINCT over the computed key (one term, one id).
 */
public class LmdbNativeRowPathComputedBindTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI name = vf.createIRI(EX, "name");
			IRI tag = vf.createIRI(EX, "tag");
			conn.add(vf.createIRI(EX, "s1"), name, vf.createLiteral("alexander"));
			conn.add(vf.createIRI(EX, "s2"), name, vf.createLiteral("bartholomew"));
			conn.add(vf.createIRI(EX, "s3"), name, vf.createLiteral("alexander"));
			conn.add(vf.createIRI(EX, "t1"), tag, vf.createLiteral("ALEXANDER"));
		}
	}

	@AfterEach
	public void tearDown() {
		repository.shutDown();
	}

	private List<BindingSet> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeEnabled));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static List<String> strings(List<BindingSet> rows, String name) {
		// a List, not a Set: the assertions are multiset assertions (duplicate computed values must survive)
		return rows.stream().map(row -> row.getValue(name).stringValue()).collect(Collectors.toList());
	}

	private void assertDifferential(String query) {
		List<BindingSet> generic = rows(query, false);
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		List<BindingSet> nativeRows = rows(query, true);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get())
				.as("the computed BIND must compile natively, not as a generic island:\n%s", query)
				.isEqualTo(islandsBefore);
		assertThat(nativeRows).as("row multiset must match generic for:\n%s", query)
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	@Test
	public void computedBindProjectsInternedValue() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?k WHERE { ?s ex:name ?n . BIND(UCASE(?n) AS ?k) }";
		assertThat(strings(rows(query, false), "k")).containsExactlyInAnyOrder("ALEXANDER", "BARTHOLOMEW",
				"ALEXANDER");
		assertDifferential(query);
	}

	@Test
	public void filterOverComputedBindRoutesThroughGenericBridge() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s WHERE { ?s ex:name ?n . BIND(UCASE(?n) AS ?k) FILTER(?k = \"ALEXANDER\") }";
		assertThat(rows(query, false)).hasSize(2);
		assertDifferential(query);
	}

	@Test
	public void computedBindJoinsAgainstStoredDataThroughCanonicalIds() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?t WHERE { ?s ex:name ?n . BIND(UCASE(?n) AS ?k) . ?t ex:tag ?k }";
		assertThat(rows(query, false)).as("generic: the computed key must join the stored tag").hasSize(2);
		assertDifferential(query);
	}

	@Test
	public void distinctOverComputedBindDeduplicatesByTerm() {
		String query = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT DISTINCT ?k WHERE { ?s ex:name ?n . BIND(UCASE(?n) AS ?k) }";
		assertThat(strings(rows(query, false), "k")).containsExactlyInAnyOrder("ALEXANDER", "BARTHOLOMEW");
		assertDifferential(query);
	}
}
